<?php $title = $category['name']; $metaDescription = $category['description'] ?? 'Nextlab ürün kategorisi'; ?>
<section class="page-hero"><div class="container"><h1><?= e($category['name']) ?></h1><?php $items=[['label'=>'Ürünler','url'=>url('urunler')],['label'=>$category['name']]]; require __DIR__ . '/../components/breadcrumb.php'; ?></div></section>
